INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('property-sales','Property Sales','Buy a home, land or investment property with confidence.','We help you find the right property for your budget, arrange inspections, check the title documents and guide you through a safe, transparent payment and handover.','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1600&q=80',0);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('rentals-leasing','Rentals & Leasing','Flats, houses and offices to rent, without the stress.','Tell us your budget and preferred area. We shortlist verified properties, arrange viewings and handle the tenancy agreement so you can move in quickly.','https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=1600&q=80',1);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('short-lets','Short-let Apartments','Furnished apartments by the night or week.','Fully furnished, serviced apartments for business trips, holidays and visiting family, with power, Wi-Fi and security included.','https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=1600&q=80',2);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('property-management','Property Management','We look after your property and your tenants.','Rent collection, tenant screening, repairs and maintenance, and regular reports, so landlords can earn from their property without the daily headaches.','https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1600&q=80',3);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('land-documentation','Land & Documentation','Verified land and help with your title documents.','We sell verified plots and help with searches at the land registry, survey plans, deeds of assignment and Certificate of Occupancy applications.','https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1600&q=80',4);
INSERT INTO services (slug,title,summary,description,image,sort_order) VALUES ('valuation-advisory','Valuation & Advisory','Know what a property is really worth.','Independent valuations and honest advice for buyers, sellers and investors, including rental yield and resale potential.','https://images.unsplash.com/photo-1582407947304-fd86f028f716?auto=format&fit=crop&w=1600&q=80',5);
