INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Do I pay to inspect a property?', 'It depends on the property. When you book, we''ll confirm the time, the meeting point and any inspection fee before you go, so there are no surprises.', 0),
  ('What fees should I expect when renting?', 'Besides the rent, there are usually agency and legal fees, and sometimes a service charge or caution deposit. We give you the full breakdown in writing before you pay anything.', 1),
  ('Are your properties verified?', 'Yes. We inspect each property and check its title documents before listing it. Ask us for the documents of any property you''re interested in.', 2),
  ('Can I pay in instalments?', 'Some properties and plots come with a payment plan. It''s shown in the property''s details, or ask an agent and we''ll tell you the options.', 3),
  ('Can you help me sell or let my property?', 'Yes. Use the Tell Us What You Want page and choose Sell or Let my property, or book a valuation visit. We''ll advise on price, take photos and find buyers or tenants.', 4),
  ('How do I book an inspection?', 'Click Book an Inspection on any property, or use the booking page. Choose a day and time and we''ll confirm by phone or WhatsApp.', 5);
